UPDATE external_keys
SET display_name = #{params.DisplayName},
    geo = #{params.Geo},
    provider_config = CAST(#{params.ProviderConfig,sensitive=true} AS jsonb),
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND external_id = #{params.ExternalID}
AND deleted_at IS NULL
RETURNING

UPDATE external_keys
SET deleted_at = COALESCE(deleted_at, NOW()),
    updated_at = NOW()
WHERE organization_uuid = #{organizationUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
